import type { OdooFieldDef, OdooFieldsGet } from "../types/index.js";

/** First line of every file `generateTypesFile` writes. */
export const TYPEGEN_HEADER =
  "// Generated by @vvhybe/odoo-client typegen — do not edit by hand.";

/** A name TypeScript accepts as is, unquoted. */
const IDENTIFIER = /^[A-Za-z_$][A-Za-z0-9_$]*$/;

/**
 * The interface name of an Odoo model: its name in PascalCase, letters and
 * digits only. `pos.restock.request.line` → `PosRestockRequestLine`. A name
 * that would start with a digit, or be empty, is prefixed with `Model`.
 */
export function modelInterfaceName(model: string): string {
  const name = model
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("");
  return /^[A-Za-z]/.test(name) ? name : `Model${name}`;
}

/**
 * TypeScript source of one exported interface for `model`, with each field
 * typed the way `search_read` returns it. Fields are sorted by name.
 */
export function generateModelTypes(
  model: string,
  fields: OdooFieldsGet,
): string {
  const names = Object.keys(fields).sort((a, b) => a.localeCompare(b, "en"));
  const properties = names.map((name) => {
    const field = fields[name]!;
    const type = name === "id" ? "number" : fieldType(field);
    // Field names come from the server: quote any that is not a plain
    // identifier, so it can never close the interface or add code.
    const key = IDENTIFIER.test(name) ? name : JSON.stringify(name);
    return `  /** ${fieldComment(field)} */\n  ${key}: ${type};`;
  });
  return [
    `export interface ${modelInterfaceName(model)} {`,
    ...properties,
    "}",
  ].join("\n");
}

/** A whole generated file: the header, then one interface per model, in order. */
export function generateTypesFile(
  models: { model: string; fields: OdooFieldsGet }[],
): string {
  const blocks = models.map(({ model, fields }) =>
    generateModelTypes(model, fields),
  );
  return `${TYPEGEN_HEADER}\n\n${blocks.join("\n\n")}\n`;
}

/** The value `search_read` returns for a field of this type. */
function fieldType(field: OdooFieldDef): string {
  switch (field.type) {
    case "char":
    case "text":
    case "html":
    case "date":
    case "datetime":
    case "binary":
    case "reference":
      return "string | false";
    case "integer":
    case "float":
    case "monetary":
      return "number";
    case "boolean":
      return "boolean";
    case "selection":
      return selectionType(field.selection);
    case "many2one":
      return "[number, string] | false";
    case "one2many":
    case "many2many":
      return "number[]";
    case "many2one_reference":
      return "number | false";
    default:
      // json, properties, properties_definition and any newer type
      return "unknown";
  }
}

function selectionType(selection: OdooFieldDef["selection"]): string {
  if (!selection?.length) return "string | false";
  const literals = selection.map(([key]) => JSON.stringify(key));
  return `${literals.join(" | ")} | false`;
}

/** Label, relation and date format, safe inside a block comment. */
function fieldComment(field: OdooFieldDef): string {
  let comment = field.string;
  if (field.relation) comment += ` (${field.relation})`;
  if (field.type === "date") comment += " — YYYY-MM-DD";
  if (field.type === "datetime") comment += " — YYYY-MM-DD HH:MM:SS, UTC";
  return comment.replace(/\*\//g, "*\\/");
}
